        "type": "mcq",
        "figure": "assets/images/quiz/chem/chem_amino_p1_q58.png",
        "question": "Histidine là một trong những amino acid thiết yếu đối với cơ thể con người. Với mỗi môi trường có giá trị pH bằng 4,0; 7,6; 12,0, coi histidine chỉ tồn tại ở dạng cho dưới đây:<br>- pH = 4,0: Dạng (I) mang điện tích dương (+1)<br>- pH = 7,6: Dạng (II) ion lưỡng cực (điện tích tổng bằng 0)<br>- pH = 12,0: Dạng (III) mang điện tích âm (-1)<br>Trong quá trình điện di, ion sẽ di chuyển về phía điện cực trái dấu với ion. Cho các nhận định sau về quá trình điện di của histidine:<br>(a) Với môi trường pH = 7,6 thì dạng (II) hầu như không dịch chuyển về các điện cực.<br>(b) Với môi trường pH = 4,0 thì dạng (I) di chuyển về phía cực âm.<br>(c) Với môi trường pH = 12,0 thì dạng (III) di chuyển về phía cực dương.<br>(d) Với môi trường pH = 7,6 thì dạng (II) di chuyển về phía cực âm.<br>Các nhận định đúng là",
        "options": {
          "A": "(a), (b), (d).",
          "B": "(a), (c), (d).",
          "C": "(b), (c), (d).",
          "D": "(a), (b), (c)."
        },
        "answer": "D",
        "explanation": "Ở pH = 7,6, dạng (II) trung hòa điện nên không dịch chuyển &rarr; (a) đúng, (d) sai.<br>Ở pH = 4,0, dạng (I) tích điện dương nên di chuyển về cực âm &rarr; (b) đúng.<br>Ở pH = 12,0, dạng (III) tích điện âm nên di chuyển về cực dương &rarr; (c) đúng.<br>Các nhận định đúng là (a), (b), (c).<br>Chọn <b>D</b>."
