        "explanation": "• <b>a) Đúng:</b> Ở pH = 6 < pI(Lys) = 9,7 nên Lys tồn tại ở dạng cation, dịch chuyển về phía cực âm.<br>• <b>b) Đúng:</b> Ở pH = 6 > pI(Glu) = 3,2 nên Glu tồn tại ở dạng anion, dịch chuyển về phía cực dương. Còn Gly có pI ≈ 6 tồn tại ở dạng ion lưỡng cực hầu như không di chuyển.<br>• <b>c) Sai:</b> Tripeptide X có 2 liên kết peptide và phân tử Glu có thêm 1 nhóm -COOH tự do ở nhánh, do đó 1 mol X tác dụng tối đa với 4 mol NaOH.<br>• <b>d) Đúng:</b> Tripeptide tạo từ 3 gốc α-amino acid khác nhau (Glu, Gly, Lys) có 3! = 6 đồng phân cấu tạo: Glu-Gly-Lys, Glu-Lys-Gly, Gly-Glu-Lys, Gly-Lys-Glu, Lys-Gly-Glu, Lys-Glu-Gly."
